namespace Jeninnet.Localization.Analyzers.Localizability.CodeFixes;

/// <summary>
/// Code fixes for the localizability analyzer: JLNLOC001 (literal to <c>*Keys</c>
/// constant) and JLNLOC002 (concatenation to interpolation).
/// </summary>
/// <remarks>
/// JLNLOC001: when the flagged literal equals a
/// <c>const string</c> in a <c>*Keys</c> class (hand-written like
/// <c>ReferenceKeys</c> or generated by), offer to reference that constant.
/// Fully namespace-qualified replacement, so no usings change: mechanical and
/// behavior-preserving (same string value, compile-time name). Literals with no
/// matching constant get no fix — the diagnostic stays until the author moves the
/// text to a catalog.
/// <para>
/// JLNLOC002: when the flagged span is a <c>+</c> chain of string literals and
/// expressions, offer to convert it to an interpolated string. Text parts are
/// escaped and every non-literal operand becomes a hole with the original
/// expression untouched, so the conversion is behavior-preserving. Multiline
/// text parts get no fix (interpolation would need verbatim re-quoting).
/// </para>
/// Lives in its own assembly because fixes require Microsoft.CodeAnalysis.Workspaces,
/// which RS1038 forbids in analyzer assemblies; the DLL travels inside the analyzer
/// package. Diagnostic IDs mirror the analyzer descriptors.
/// </remarks>
[ExportCodeFixProvider(LanguageNames.CSharp, Name = nameof(LocalizabilityCodeFixProvider))]
public sealed class LocalizabilityCodeFixProvider : CodeFixProvider {
    /// <summary>
    /// The fixed diagnostic IDs (mirror the analyzer descriptors).
    /// </summary>
    internal static readonly ImmutableArray<string> DiagnosticIds = ["JLNLOC001", "JLNLOC002"];

    /// <inheritdoc/>
    public override ImmutableArray<string> FixableDiagnosticIds =>
        DiagnosticIds;

    /// <inheritdoc/>
    public override FixAllProvider? GetFixAllProvider() => null;

    /// <inheritdoc/>
    public override async Task RegisterCodeFixesAsync(CodeFixContext context) {
        foreach(var diagnostic in context.Diagnostics) {
            if(diagnostic.Id.Equals("JLNLOC001", StringComparison.Ordinal)) {
                await RegisterKeysFixAsync(context, diagnostic).ConfigureAwait(false);
            } else if(diagnostic.Id.Equals("JLNLOC002", StringComparison.Ordinal)) {
                await RegisterInterpolationFixAsync(context, diagnostic).ConfigureAwait(false);
            }
        }
    }

    /// <summary>
    /// Registers the keys fix.
    /// </summary>
    /// <param name="context">The context.</param>
    /// <param name="diagnostic">The diagnostic.</param>
    /// <returns>A task that completes the registration.</returns>
    private static async Task RegisterKeysFixAsync(CodeFixContext context, Diagnostic diagnostic) {
        var literal = await LiteralAtAsync(context, diagnostic).ConfigureAwait(false);
        if(literal is null || literal.Token.ValueText.Length == 0) {
            return;
        }

        var document = context.Document;
        var model = await document.GetSemanticModelAsync(context.CancellationToken).ConfigureAwait(false);
        if(model?.Compilation is null) {
            return;
        }

        var match = FindConstant(model.Compilation, literal.Token.ValueText);
        if(match is null) {
            return;
        }

        context.RegisterCodeFix(
            CodeAction.Create(
                title: $"Use {match.TypeName}.{match.FieldName}",
                createChangedDocument: cancellationToken => ApplyFixAsync(document, literal, match.QualifiedName, cancellationToken),
                equivalenceKey: "JLNLOC001_Use_" + match.QualifiedName),
            diagnostic);
    }

    /// <summary>
    /// Finds the flagged literal for the keys fix.
    /// </summary>
    /// <param name="context">The context.</param>
    /// <param name="diagnostic">The diagnostic.</param>
    /// <returns>The literal, or null when absent.</returns>
    private static async Task<LiteralExpressionSyntax?> LiteralAtAsync(CodeFixContext context, Diagnostic diagnostic) {
        if(diagnostic.Location.SourceTree is null) {
            return null;
        }

        var document = context.Document;
        var root = await document.GetSyntaxRootAsync(context.CancellationToken).ConfigureAwait(false);
        return root?.FindNode(diagnostic.Location.SourceSpan).FirstAncestorOrSelf<LiteralExpressionSyntax>();
    }

    /// <summary>
    /// Registers the interpolation fix.
    /// </summary>
    /// <param name="context">The context.</param>
    /// <param name="diagnostic">The diagnostic.</param>
    /// <returns>A task that completes the registration.</returns>
    private static async Task RegisterInterpolationFixAsync(CodeFixContext context, Diagnostic diagnostic) {
        if(diagnostic.Location.SourceTree is null) {
            return;
        }

        var document = context.Document;
        var root = await document.GetSyntaxRootAsync(context.CancellationToken).ConfigureAwait(false);
        var concatenation = root?.FindNode(diagnostic.Location.SourceSpan).FirstAncestorOrSelf<BinaryExpressionSyntax>();
        if(concatenation is null || !concatenation.IsKind(SyntaxKind.AddExpression)) {
            return;
        }

        var parts = FlattenConcatenation(concatenation);
        if(parts.Count == 0) {
            return;
        }

        var contents = new List<InterpolatedStringContentSyntax>(parts.Count);
        foreach(var part in parts) {
            if(part is LiteralExpressionSyntax literal) {
                var text = literal.Token.ValueText;
                if(text.Contains('\r') || text.Contains('\n')) {
                    return;
                }

                contents.Add(SyntaxFactory.InterpolatedStringText(SyntaxFactory.Token(
                    default,
                    SyntaxKind.InterpolatedStringTextToken,
                    EscapeBraces(text),
                    EscapeBraces(text),
                    default)));
            } else {
                contents.Add(SyntaxFactory.Interpolation(part));
            }
        }

        var interpolated = SyntaxFactory.InterpolatedStringExpression(
            SyntaxFactory.Token(SyntaxKind.InterpolatedStringStartToken),
            SyntaxFactory.List(contents),
            SyntaxFactory.Token(SyntaxKind.InterpolatedStringEndToken))
            .WithTriviaFrom(concatenation);

        context.RegisterCodeFix(
            CodeAction.Create(
                title: "Convert to interpolated string",
                createChangedDocument: cancellationToken => ReplaceNodeAsync(document, concatenation, interpolated, cancellationToken),
                equivalenceKey: "JLNLOC002_UseInterpolation"),
            diagnostic);
    }

    /// <summary>
    /// Flattens a left-associative <c>+</c> chain into its parts.
    /// </summary>
    /// <param name="binary">The binary expression.</param>
    /// <returns>The parts in source order.</returns>
    private static List<ExpressionSyntax> FlattenConcatenation(BinaryExpressionSyntax binary) {
        var parts = new List<ExpressionSyntax>();
        FlattenInto(binary.Left, parts);
        FlattenInto(binary.Right, parts);
        return parts;
    }

    /// <summary>
    /// Flattens into.
    /// </summary>
    /// <param name="node">The node.</param>
    /// <param name="parts">The parts.</param>
    private static void FlattenInto(ExpressionSyntax node, List<ExpressionSyntax> parts) {
        if(node is BinaryExpressionSyntax nested && nested.IsKind(SyntaxKind.AddExpression)) {
            FlattenInto(nested.Left, parts);
            FlattenInto(nested.Right, parts);
            return;
        }

        parts.Add(node);
    }

    /// <summary>
    /// Escapes braces for interpolated string text.
    /// </summary>
    /// <param name="text">The text.</param>
    /// <returns>The escaped text.</returns>
    private static string EscapeBraces(string text) =>
        text.Replace("{", "{{").Replace("}", "}}");

    /// <summary>
    /// Replaces node.
    /// </summary>
    /// <param name="document">The document.</param>
    /// <param name="oldNode">The old node.</param>
    /// <param name="newNode">The new node.</param>
    /// <param name="cancellationToken">A token to cancel the operation.</param>
    /// <returns>A task whose result is node.</returns>
    private static async Task<Document> ReplaceNodeAsync(Document document, SyntaxNode oldNode, SyntaxNode newNode, CancellationToken cancellationToken) {
        var root = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
        return root is null ? document : document.WithSyntaxRoot(root.ReplaceNode(oldNode, newNode));
    }

    /// <summary>
    /// Finds constant.
    /// </summary>
    /// <param name="compilation">The compilation.</param>
    /// <param name="value">The value.</param>
    /// <returns>The constant result.</returns>
    internal static ConstantMatch? FindConstant(Compilation compilation, string value) {
        if(compilation is null) {
            throw new ArgumentNullException(nameof(compilation));
        }

        if(value is null) {
            throw new ArgumentNullException(nameof(value));
        }

        ConstantMatch? best = null;
        foreach(var type in AllSourceTypes(compilation.GlobalNamespace)) {
            if(!type.Name.EndsWith("Keys", StringComparison.Ordinal)) {
                continue;
            }

            foreach(var member in type.GetMembers()) {
                if(member is not IFieldSymbol field ||
                   !field.IsConst ||
                   field.Type?.SpecialType != SpecialType.System_String ||
                   !field.HasConstantValue ||
                   (field.ConstantValue as string) != value) {
                    continue;
                }

                var qualified = type.ToDisplayString() + "." + field.Name;
                var candidate = new ConstantMatch(type.Name, field.Name, qualified);
                if(best is null || string.CompareOrdinal(candidate.QualifiedName, best.QualifiedName) < 0) {
                    best = candidate;
                }
            }
        }

        return best;
    }

    /// <summary>
    /// Applies fix.
    /// </summary>
    /// <param name="document">The document.</param>
    /// <param name="literal">The literal.</param>
    /// <param name="qualifiedName">The qualified name.</param>
    /// <param name="cancellationToken">A token to cancel the operation.</param>
    /// <returns>A task whose result is fix.</returns>
    private static async Task<Document> ApplyFixAsync(Document document, LiteralExpressionSyntax literal, string qualifiedName, CancellationToken cancellationToken) {
        var root = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(false);
        if(root is null) {
            return document;
        }

        var replacement = Microsoft.CodeAnalysis.CSharp.SyntaxFactory.ParseExpression(qualifiedName)
            .WithTriviaFrom(literal);
        return document.WithSyntaxRoot(root.ReplaceNode(literal, replacement));
    }

    /// <summary>
    /// Performs the all source types operation.
    /// </summary>
    /// <param name="space">The space.</param>
    /// <returns>The all source types sequence.</returns>
    private static IEnumerable<INamedTypeSymbol> AllSourceTypes(INamespaceSymbol space) {
        foreach(var member in space.GetMembers()) {
            if(member is INamespaceSymbol nested) {
                foreach(var type in AllSourceTypes(nested)) {
                    yield return type;
                }
            } else if(member is INamedTypeSymbol type &&
                      type.Locations.Any(static location => location.IsInSource)) {
                yield return type;

                foreach(var nestedType in AllNestedTypes(type)) {
                    yield return nestedType;
                }
            }
        }
    }

    /// <summary>
    /// Performs the all nested types operation.
    /// </summary>
    /// <param name="type">The type.</param>
    /// <returns>The all nested types sequence.</returns>
    private static IEnumerable<INamedTypeSymbol> AllNestedTypes(INamedTypeSymbol type) {
        foreach(var member in type.GetMembers()) {
            if(member is INamedTypeSymbol nested && nested.Locations.Any(static location => location.IsInSource)) {
                yield return nested;

                foreach(var deeper in AllNestedTypes(nested)) {
                    yield return deeper;
                }
            }
        }
    }

    /// <summary>
    /// Represents a constant match.
    /// </summary>
    /// <param name="typeName">The type name.</param>
    /// <param name="fieldName">The field name.</param>
    /// <param name="qualifiedName">The qualified name.</param>
    internal sealed class ConstantMatch(string typeName, string fieldName, string qualifiedName) {
        /// <summary>
        /// Gets the type name.
        /// </summary>
        public string TypeName { get; } = typeName;

        /// <summary>
        /// Gets the field name.
        /// </summary>
        public string FieldName { get; } = fieldName;

        /// <summary>
        /// Gets the qualified name.
        /// </summary>
        public string QualifiedName { get; } = qualifiedName;
    }
}
